"""GPU geometry and core PDM components shared by the metric implementations.

The metric stage is batched on the selected device; version-specific terms are
combined by the public scorer.
"""

from __future__ import annotations

from dataclasses import dataclass

import torch

from t4_e2e_devkit.evaluation.gpu.areas import (
    drivable_area_compliance_torch,
    driving_direction_compliance_torch,
    ego_areas_torch,
    points_in_polygons_torch,
)
from t4_e2e_devkit.evaluation.gpu.collisions import (
    TrackTensors,
    no_at_fault_collision_torch,
    ttc_torch,
)
from t4_e2e_devkit.evaluation.gpu.comfort import ego_is_comfortable_torch
from t4_e2e_devkit.evaluation.gpu.geometry import (
    CENTER,
    TorchPolyline,
    raw_progress_torch,
    state_array_to_coords_torch,
)
from t4_e2e_devkit.evaluation.gpu.scene import MapTensors


@dataclass
class VehicleTensors:
    half_length: float
    half_width: float
    rear_axle_to_center: float


@dataclass
class WindowScene:
    """Everything one window contributes to the metric stage."""

    tracks: TrackTensors
    map_tensors: MapTensors
    centerline: TorchPolyline
    route_present: bool = True


def score_simulated_window(
    simulated: torch.Tensor,  # [P, T+1, 11] simulated ego states
    scene: WindowScene,
    vehicle: VehicleTensors,
    interval_length: float,
    progress_distance_threshold: float = 5.0,
) -> tuple[torch.Tensor, torch.Tensor]:  # total [P], core components [P, 6]
    n_proposals, n_time = simulated.shape[:2]
    dtype, device = simulated.dtype, simulated.device

    coords = state_array_to_coords_torch(
        simulated,
        vehicle.half_length,
        vehicle.half_width,
        vehicle.rear_axle_to_center,
    )  # [P, T, 5, 2]
    corners = coords[..., :4, :]
    centers = coords[..., CENTER, :]

    # Exact reach prefilter.  Containment can only change for points inside a
    # polygon and SAT intersection implies bbox overlap, so map polygons and
    # tracks whose bbox misses the reach bbox cannot influence any metric.
    # The TTC projection displaces ego corners by at most 0.9 s at the fastest
    # simulated speed, which is the track margin.
    flat_corners = corners.reshape(-1, 2)
    reach_min = flat_corners.amin(dim=0)
    reach_max = flat_corners.amax(dim=0)
    scene_tracks = scene.tracks
    map_tensors = scene.map_tensors
    if map_tensors.bboxes is not None:
        boxes = map_tensors.bboxes
        keep = (
            (boxes[:, 0] <= reach_max[0])
            & (boxes[:, 2] >= reach_min[0])
            & (boxes[:, 1] <= reach_max[1])
            & (boxes[:, 3] >= reach_min[1])
        )
        map_tensors = map_tensors.restricted_to(keep)
    if scene_tracks.bboxes is not None and scene_tracks.bboxes.shape[0]:
        from t4_e2e_devkit.planning.simulation.planner.pdm_planner.utils.pdm_enums import (
            StateIndex,
        )

        margin = (
            torch.hypot(
                simulated[..., StateIndex.VELOCITY_X],
                simulated[..., StateIndex.VELOCITY_Y],
            ).amax()
            * 0.9
        )
        boxes = scene_tracks.bboxes
        keep = (
            (boxes[:, 0] <= reach_max[0] + margin)
            & (boxes[:, 2] >= reach_min[0] - margin)
            & (boxes[:, 1] <= reach_max[1] + margin)
            & (boxes[:, 3] >= reach_min[1] - margin)
        )
        scene_tracks = scene_tracks.restricted_to(keep)

    multiple_lanes, non_drivable, oncoming = ego_areas_torch(
        corners,
        centers,
        map_tensors.edge_starts,
        map_tensors.edge_ends,
        map_tensors.drivable_area_indices,
        map_tensors.lane_indices,
        map_tensors.on_route_lane_indices,
    )
    fault_area = multiple_lanes | non_drivable

    if map_tensors.intersection_indices.numel():
        rear_axle_hits = points_in_polygons_torch(
            simulated[..., :2].reshape(-1, 2),
            map_tensors.edge_starts[map_tensors.intersection_indices],
            map_tensors.edge_ends[map_tensors.intersection_indices],
        )
        in_intersection = (
            rear_axle_hits.any(dim=0).reshape(n_proposals, n_time)
        )
    else:
        in_intersection = torch.zeros(
            (n_proposals, n_time), dtype=torch.bool, device=device
        )

    nc = no_at_fault_collision_torch(corners, simulated, fault_area, scene_tracks)
    dac = drivable_area_compliance_torch(non_drivable).to(dtype)
    ddc = driving_direction_compliance_torch(
        centers, oncoming, interval_length
    ).to(dtype)
    ttc = ttc_torch(
        corners,
        simulated,
        fault_area,
        in_intersection,
        scene_tracks,
        interval_length,
    ).to(dtype)

    time_steps = (
        torch.arange(n_time, dtype=dtype, device=device) * interval_length
    )
    comfort = (
        ego_is_comfortable_torch(simulated, time_steps).all(dim=-1).to(dtype)
    )

    raw_progress = raw_progress_torch(centers, scene.centerline)

    # Core gates and weighted terms; version-specific aggregation is owned by
    # the public scorer.
    multiplicative = nc.to(dtype) * dac
    raw = raw_progress * multiplicative
    # ``ego_progress`` is normalised across the proposals in *this call*, and that
    # is the contract rather than a default: the official scorer's form saturates
    # to 1.0 for every proposal short of ``progress_distance_threshold`` and so
    # cannot rank proposals at all, which is the one job a proposal oracle has.
    # A caller that wants the official quantity goes through the public scorer,
    # which overrides this component anyway.
    #
    # A ``normalize_progress_across_proposals`` flag used to sit here promising to
    # switch this. Both of its branches computed this same reduction, so it never
    # switched anything, and it defaulted to ``False`` while behaving like
    # ``True``. Removed rather than implemented: no caller passed it, so dropping
    # it changes no score, whereas giving the ``False`` branch its literal meaning
    # would have silently re-normalised every existing caller's labels.
    max_raw = raw.max()
    fast = max_raw > progress_distance_threshold
    ep = torch.ones_like(raw)
    ep = torch.where(fast, raw / torch.where(fast, max_raw, torch.ones_like(max_raw)), ep)
    ep = torch.where((~fast) & (multiplicative == 0), torch.zeros_like(ep), ep)

    weighted = (5.0 * ep + 5.0 * ttc + 2.0 * comfort + 0.0 * ddc) / 12.0
    total = multiplicative * weighted

    components = torch.stack([nc.to(dtype), dac, ddc, ttc, ep, comfort], dim=-1)
    return total, components
